'use strict'

const {
  getRequestOrigin,
  getInterceptorOrigin,
  makeCacheKey,
  normalizeHeaders,
  assertCacheKey,
  assertCacheValue,
  assertCacheMethods,
  assertCacheStore,
  makeDeduplicationKey
} = require('../../../lib/util/cache')
const { kRequestOrigin } = require('../../../lib/core/symbols')

describe('lib/util/cache origins', () => {
  test('getRequestOrigin prefers the internal request origin option', () => {
    expect(getRequestOrigin({ origin: 'http://example.com' })).toBe('http://example.com')
    expect(getRequestOrigin({ origin: new URL('http://example.com/') })).toEqual(new URL('http://example.com/'))
    expect(getRequestOrigin({ origin: 'http://example.com', [kRequestOrigin]: 'http://override.test' })).toBe('http://override.test')
    expect(getRequestOrigin({ origin: 'http://example.com', [kRequestOrigin]: null })).toBeNull()
  })

  test('getRequestOrigin rejects non-string and non-URL origins', () => {
    expect(getRequestOrigin({})).toBeNull()
    expect(getRequestOrigin({ origin: 42 })).toBeNull()
    expect(getRequestOrigin({ origin: { href: 'http://example.com' } })).toBeNull()
  })

  test('getInterceptorOrigin falls back to the request origin when unspecified', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com/path' }, undefined)).toBe('http://example.com/path')
    expect(getInterceptorOrigin({}, undefined)).toBeNull()
  })

  test('getInterceptorOrigin returns null for an explicit null or cross-origin interceptor', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, null)).toBeNull()
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, 'http://other.test')).toBeNull()
    expect(getInterceptorOrigin({ origin: 'http://example.com/a' }, 'http://example.com')).toBe('http://example.com')
  })

  test('getInterceptorOrigin keeps a configured interceptor origin when the request origin cannot be parsed', () => {
    expect(getInterceptorOrigin({ origin: 'not a url' }, 'http://interceptor.test')).toBe('http://interceptor.test')
  })

  test('getInterceptorOrigin compares the normalized origin of URL request origins', () => {
    expect(getInterceptorOrigin({ origin: new URL('http://example.com/deep/path') }, 'http://example.com')).toBe('http://example.com')
    expect(getInterceptorOrigin({ origin: new URL('https://example.com') }, 'http://example.com')).toBeNull()
  })
})

describe('lib/util/cache makeCacheKey', () => {
  test('uses a default path and forwards method and headers', () => {
    const headers = { accept: 'text/plain' }
    const key = makeCacheKey({ origin: 'http://example.com', method: 'GET', headers })

    expect(key).toEqual({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers
    })
    expect(key.headers).toBe(headers)
  })

  test('serializes query options onto an existing path', () => {
    const key = makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: { b: '2', a: '1' }
    })

    expect(key.path).toBe('/search?b=2&a=1')
  })

  test('does not append query options when the path already contains a query or fragment', () => {
    expect(makeCacheKey({ origin: 'http://example.com', method: 'GET', path: '/a?x=1', query: { y: '2' } }).path).toBe('/a?x=1')
    expect(makeCacheKey({ origin: 'http://example.com', method: 'GET', path: '/a#frag', query: { y: '2' } }).path).toBe('/a#frag')
  })

  test('converts URL origins to strings and honors the internal request origin', () => {
    expect(makeCacheKey({ origin: new URL('http://example.com/base'), method: 'GET' }).origin).toBe('http://example.com/base')
    expect(makeCacheKey({ origin: 'http://ignored.test', [kRequestOrigin]: 'http://used.test', method: 'POST', path: '/p' }).origin).toBe('http://used.test')
  })

  test('throws a descriptive error when no usable origin is available', () => {
    expect(() => makeCacheKey({ method: 'GET' })).toThrow(new Error('opts.origin is undefined'))
    expect(() => makeCacheKey({ origin: 123, method: 'GET' })).toThrow(new Error('opts.origin is undefined'))
  })

  test('uses an explicitly supplied origin argument instead of deriving it from options', () => {
    expect(makeCacheKey({ origin: 'http://example.com', method: 'GET' }, 'http://explicit.test').origin).toBe('http://explicit.test')
  })
})

describe('lib/util/cache normalizeHeaders', () => {
  test('returns an empty object when headers are absent', () => {
    expect(normalizeHeaders({})).toEqual({})
    expect(normalizeHeaders({ headers: null })).toEqual({})
    expect(normalizeHeaders({ headers: undefined })).toEqual({})
  })

  test('lowercases object header names and merges duplicate keys', () => {
    expect(normalizeHeaders({
      headers: {
        'X-Request-Id': 'one',
        'x-request-id': ['two', 'three'],
        Accept: 'text/plain'
      }
    })).toEqual({
      'x-request-id': ['one', 'two', 'three'],
      accept: 'text/plain'
    })
  })

  test('copies array header values instead of modifying the input', () => {
    const original = ['a', 'b']
    const normalized = normalizeHeaders({ headers: { 'x-multi': original } })

    expect(normalized['x-multi']).toEqual(['a', 'b'])
    expect(normalized['x-multi']).not.toBe(original)
    original.push('c')
    expect(normalized['x-multi']).toEqual(['a', 'b'])
  })

  test('accepts a flat alternating key/value array', () => {
    expect(normalizeHeaders({ headers: ['X-A', 'one', 'x-a', 'two'] })).toEqual({
      'x-a': ['one', 'two']
    })
  })

  test('accepts an array of header pairs', () => {
    expect(normalizeHeaders({ headers: [['X-A', 'one'], ['X-B', 'two']] })).toEqual({
      'x-a': 'one',
      'x-b': 'two'
    })
  })

  test('accepts a non-array iterable of header pairs', () => {
    expect(normalizeHeaders({ headers: new Map([['X-A', 'one'], ['X-B', 'two']]) })).toEqual({
      'x-a': 'one',
      'x-b': 'two'
    })
  })

  test('converts Buffer values in flat arrays to latin1 strings', () => {
    expect(normalizeHeaders({ headers: ['x-buffer', [Buffer.from('hi')]] })).toEqual({
      'x-buffer': ['hi']
    })
  })

  test('rejects non-object headers', () => {
    expect(() => normalizeHeaders({ headers: 'accept: text/plain' })).toThrow('opts.headers is not an object')
  })

  test('rejects malformed flat arrays', () => {
    expect(() => normalizeHeaders({ headers: ['x-a'] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: ['x-a', 1] })).toThrow('opts.headers is not a valid header map')
  })

  test('rejects malformed header pair arrays and iterables', () => {
    expect(() => normalizeHeaders({ headers: [['x-a']] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [[1, 'one']] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [['x-a', 1]] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [['x-a', 'one'], 'x-b'] })).toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: new Set(['x-a']) })).toThrow('opts.headers is not a valid header map')
  })

  test('stores a __proto__ header as an own data property', () => {
    const normalized = normalizeHeaders({ headers: JSON.parse('{"__proto__":"value"}') })

    expect(Object.hasOwn(normalized, '__proto__')).toBe(true)
    expect(normalized.__proto__).toBe('value')
    expect(Object.getPrototypeOf(normalized)).toBe(Object.prototype)
  })
})

describe('lib/util/cache assertions', () => {
  test('assertCacheKey accepts a well-formed key', () => {
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/' })).not.toThrow()
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/', headers: {} })).not.toThrow()
  })

  test('assertCacheKey rejects non-objects and missing string fields', () => {
    expect(() => assertCacheKey('key')).toThrow('expected key to be object, got string')
    expect(() => assertCacheKey({ method: 'GET', path: '/' })).toThrow('expected key.origin to be string, got undefined')
    expect(() => assertCacheKey({ origin: 'http://example.com', path: '/' })).toThrow('expected key.method to be string, got undefined')
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET' })).toThrow('expected key.path to be string, got undefined')
  })

  test('assertCacheKey rejects non-object headers', () => {
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/', headers: 'bad' }))
      .toThrow('expected headers to be object, got object')
  })

  test('assertCacheValue accepts a well-formed value', () => {
    expect(() => assertCacheValue({
      statusCode: 200,
      statusMessage: 'OK',
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3,
      headers: { 'content-type': 'text/plain' },
      vary: { accept: 'text/plain' },
      etag: '"abc"'
    })).not.toThrow()
  })

  test('assertCacheValue rejects missing or wrongly typed required fields', () => {
    expect(() => assertCacheValue({})).toThrow('expected value.statusCode to be number, got undefined')
    expect(() => assertCacheValue({
      statusCode: 200,
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3,
      statusMessage: 1
    })).toThrow('expected value.statusMessage to be string, got number')
    expect(() => assertCacheValue({
      statusCode: 200,
      cachedAt: '1',
      staleAt: 2,
      deleteAt: 3,
      statusMessage: 'OK'
    })).toThrow('expected value.cachedAt to be number, got string')
  })

  test('assertCacheValue validates optional fields when present', () => {
    const base = { statusCode: 200, cachedAt: 1, staleAt: 2, deleteAt: 3, statusMessage: 'OK' }
    expect(() => assertCacheValue({ ...base, headers: 'bad' })).toThrow('expected value.rawHeaders to be object, got object')
    expect(() => assertCacheValue({ ...base, vary: 'accept' })).toThrow('expected value.vary to be object, got string')
    expect(() => assertCacheValue({ ...base, etag: 123 })).toThrow('expected value.etag to be string, got number')
  })

  test('assertCacheStore accepts an object implementing the store contract', () => {
    expect(() => assertCacheStore({
      get () {},
      createWriteStream () {},
      delete () {}
    })).not.toThrow()
  })

  test('assertCacheStore rejects missing stores and methods', () => {
    expect(() => assertCacheStore(null)).toThrow('expected type of CacheStore to be a CacheStore, got null')
    expect(() => assertCacheStore('store')).toThrow('expected type of CacheStore to be a CacheStore, got string')
    expect(() => assertCacheStore({})).toThrow('CacheStore needs to have a `get()` function')
    expect(() => assertCacheStore({ get () {} })).toThrow('CacheStore needs to have a `createWriteStream()` function')
    expect(() => assertCacheStore({ get () {}, createWriteStream () {} })).toThrow('CacheStore needs to have a `delete()` function')
    expect(() => assertCacheStore({}, 'CustomStore')).toThrow('CustomStore needs to have a `get()` function')
  })

  test('assertCacheMethods accepts all safe HTTP methods', () => {
    expect(() => assertCacheMethods(['GET'])).not.toThrow()
    expect(() => assertCacheMethods(['GET', 'HEAD', 'OPTIONS', 'TRACE'])).not.toThrow()
  })

  test('assertCacheMethods rejects non-arrays, empty arrays, and unsafe methods', () => {
    expect(() => assertCacheMethods('GET')).toThrow('expected type of CacheMethods needs to be an array, got string')
    expect(() => assertCacheMethods([])).toThrow('CacheMethods needs to have at least one method')
    expect(() => assertCacheMethods(['GET', 'POST'])).toThrow('element of CacheMethods-array needs to be one of following values: GET, HEAD, OPTIONS, TRACE, got POST')
    expect(() => assertCacheMethods(['get'], 'Methods')).toThrow('element of Methods-array needs to be one of following values: GET, HEAD, OPTIONS, TRACE, got get')
  })
})

describe('lib/util/cache makeDeduplicationKey', () => {
  test('produces a stable JSON key with sorted header names', () => {
    const keyA = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { b: '2', A: '1', 'x-test': 'z' }
    })
    const keyB = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { 'x-test': 'z', A: '1', b: '2' }
    })

    expect(keyA).toBe(keyB)
    expect(JSON.parse(keyA)).toEqual(['http://example.com', 'GET', '/', { A: '1', b: '2', 'x-test': 'z' }])
  })

  test('excludes requested headers case-insensitively', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { Accept: 'text/plain', 'X-Trace': 'abc' }
    }, new Set(['x-trace']))

    expect(JSON.parse(key)[3]).toEqual({ Accept: 'text/plain' })
  })

  test('uses an empty header object when no headers are supplied', () => {
    expect(makeDeduplicationKey({ origin: 'http://example.com', method: 'GET', path: '/' }))
      .toBe(JSON.stringify(['http://example.com', 'GET', '/', {}]))
  })

  test('preserves array-valued headers', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { accept: ['text/plain', 'text/html'] }
    })

    expect(JSON.parse(key)[3]).toEqual({ accept: ['text/plain', 'text/html'] })
  })

  test('does not collide when header contents contain delimiters', () => {
    const keyA = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x:b=y' }
    })
    const keyB = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x', b: 'y' }
    })

    expect(keyA).not.toBe(keyB)
  })
})
