'use strict'

const { parseHttpDate } = require('../../../lib/util/date')

describe('lib/util/date parseHttpDate', () => {
  describe('IMF-fixdate', () => {
    test('parses the preferred HTTP date format', () => {
      const date = parseHttpDate('Sun, 06 Nov 1994 08:49:37 GMT')

      expect(date).toBeInstanceOf(Date)
      expect(date.toISOString()).toBe('1994-11-06T08:49:37.000Z')
    })

    test('validates the weekday against the calendar date', () => {
      expect(parseHttpDate('Mon, 06 Nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 07 Nov 1994 08:49:37 GMT')).toBeUndefined()
    })

    test('accepts leap days and rejects non-leap February 29', () => {
      expect(parseHttpDate('Tue, 29 Feb 2000 12:34:56 GMT').toISOString()).toBe('2000-02-29T12:34:56.000Z')
      expect(parseHttpDate('Tue, 29 Feb 1999 12:34:56 GMT')).toBeUndefined()
    })

    test('preserves years below 100 without mapping them to the 1900s', () => {
      expect(parseHttpDate('Mon, 01 Jan 0001 00:00:00 GMT').toISOString()).toBe('0001-01-01T00:00:00.000Z')
    })

    test('rejects out-of-range dates and times', () => {
      expect(parseHttpDate('Sun, 00 Nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 32 Nov 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 31 Feb 1994 08:49:37 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 24:00:00 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 23:60:00 GMT')).toBeUndefined()
      expect(parseHttpDate('Sun, 06 Nov 1994 23:59:60 GMT')).toBeUndefined()
    })

    test('rejects malformed field separators and suffixes', () => {
      expect(parseHttpDate('Sun, 06 Nov 1994 08:49:37 UTC')).toBeUndefined()
