'use strict'

const runtimeFeaturesModule = require('../../../lib/util/runtime-features')

describe('lib/util/runtime-features', () => {
  const { runtimeFeatures, default: defaultExport } = runtimeFeaturesModule

  afterEach(() => {
    runtimeFeatures.clear()
  })

  test('exports a single shared runtime feature detector', () => {
    expect(runtimeFeatures).toBe(defaultExport)
    expect(typeof runtimeFeatures.has).toBe('function')
    expect(typeof runtimeFeatures.set).toBe('function')
    expect(typeof runtimeFeatures.clear).toBe('function')
  })

  test('detects features that are available in the current Node.js runtime', () => {
    expect(runtimeFeatures.has('crypto')).toBe(true)
    expect(runtimeFeatures.has('sqlite')).toBe(true)
  })

  test('reports unknown features through a TypeError', () => {
    expect(() => runtimeFeatures.has('worker_threads')).toThrow(new TypeError('unknown feature: worker_threads'))
  })

  test('allows overriding a detected feature', () => {
    runtimeFeatures.set('crypto', false)
    expect(runtimeFeatures.has('crypto')).toBe(false)

    runtimeFeatures.set('crypto', true)
    expect(runtimeFeatures.has('crypto')).toBe(true)
  })

  test('clear removes both detections and overrides', () => {
    runtimeFeatures.set('crypto', false)
    runtimeFeatures.set('sqlite', false)

    runtimeFeatures.clear()

    expect(runtimeFeatures.has('crypto')).toBe(true)
    expect(runtimeFeatures.has('sqlite')).toBe(true)
  })

  test('rejects setting an unknown feature', () => {
    expect(() => runtimeFeatures.set('worker_threads', true)).toThrow(new TypeError('unknown feature: worker_threads'))
  })

  test('clear is safe to call repeatedly', () => {
    expect(() => {
      runtimeFeatures.clear()
      runtimeFeatures.clear()
    }).not.toThrow()
  })
})
