      [kConnected]: 1,
      [kFree]: 2,
      [kPending]: 3,
      [kQueued]: 4,
      [kRunning]: 5,
      [kSize]: 6
    }
    const stats = new PoolStats(pool)

    pool[kConnected] = 10
    pool[kFree] = 20

    expect(stats.connected).toBe(1)
    expect(stats.free).toBe(2)
  })

  test('leaves unavailable counters undefined', () => {
    const stats = new PoolStats({})

    expect(stats.connected).toBeUndefined()
    expect(stats.free).toBeUndefined()
    expect(stats.pending).toBeUndefined()
    expect(stats.queued).toBeUndefined()
    expect(stats.running).toBeUndefined()
    expect(stats.size).toBeUndefined()
  })
})
