const timers = require('../../../lib/util/timers')

describe('lib/util/timers', () => {
  beforeEach(() => {
    timers.reset()
  })

  afterEach(() => {
    timers.reset()
    jest.useRealTimers()
  })

  test('reset returns the internal clock to zero and tick advances it', () => {
    expect(timers.now()).toBe(0)

    timers.tick(1000)

    expect(timers.now()).toBeGreaterThan(0)
  })

  describe('native timer delegation', () => {
    test('delegates delays at or below the resolution threshold to native timers', () => {
      jest.useFakeTimers()
      const callback = jest.fn()

      const handle = timers.setTimeout(callback, 1000, 'argument')

      expect(handle[timers.kFastTimer]).toBeUndefined()
      jest.advanceTimersByTime(999)
      expect(callback).not.toHaveBeenCalled()

      jest.advanceTimersByTime(1)
      expect(callback).toHaveBeenCalledTimes(1)
      expect(callback).toHaveBeenCalledWith('argument')
    })

    test('clearTimeout cancels a native timer', () => {
      jest.useFakeTimers()
      const callback = jest.fn()

      const handle = timers.setTimeout(callback, 10)
      timers.clearTimeout(handle)
      jest.advanceTimersByTime(100)

      expect(callback).not.toHaveBeenCalled()
    })

    test('creates a fast timer for delays above the resolution threshold', () => {
      jest.useFakeTimers()
      const callback = jest.fn()

      const handle = timers.setTimeout(callback, 1001)

      expect(handle[timers.kFastTimer]).toBe(true)
      expect(callback).not.toHaveBeenCalled()
    })
  })

  describe('fast timers', () => {
    test('setFastTimeout invokes the callback once with its argument after the delay', () => {
      const callback = jest.fn()
      const argument = { request: true }

      timers.setFastTimeout(callback, 2000, argument)
      timers.tick(0)
      expect(callback).not.toHaveBeenCalled()

      timers.tick(2000)
      expect(callback).toHaveBeenCalledTimes(1)
      expect(callback).toHaveBeenCalledWith(argument)

      timers.tick(10000)
      expect(callback).toHaveBeenCalledTimes(1)
    })

    test('setTimeout uses a fast timer for delays above the resolution threshold', () => {
      const callback = jest.fn()

      timers.setTimeout(callback, 1001, 'fast')
      timers.tick(0)
      timers.tick(1500)

      expect(callback).toHaveBeenCalledTimes(1)
      expect(callback).toHaveBeenCalledWith('fast')
    })

    test('clearFastTimeout prevents a pending timer from running', () => {
      const callback = jest.fn()

      const handle = timers.setFastTimeout(callback, 3000)
      timers.tick(0)
      timers.clearFastTimeout(handle)
      timers.tick(10000)

      expect(callback).not.toHaveBeenCalled()
    })

    test('clearTimeout recognizes and cancels fast timers', () => {
      const callback = jest.fn()

      const handle = timers.setTimeout(callback, 2000)
      timers.tick(0)
      timers.clearTimeout(handle)
      timers.tick(10000)

      expect(callback).not.toHaveBeenCalled()
    })

    test('refresh reschedules an active timer from the current internal time', () => {
      const callback = jest.fn()
      const handle = timers.setFastTimeout(callback, 5000)

      timers.tick(0)
      timers.tick(3000)
      expect(callback).not.toHaveBeenCalled()

      handle.refresh()
      timers.tick(0)
      timers.tick(1000)
      expect(callback).not.toHaveBeenCalled()

      timers.tick(3000)
      expect(callback).toHaveBeenCalledTimes(1)
    })

    test('refresh reactivates a timer that already fired', () => {
      const callback = jest.fn()
      const handle = timers.setFastTimeout(callback, 2000)

      timers.tick(0)
      timers.tick(2000)
      expect(callback).toHaveBeenCalledTimes(1)

      handle.refresh()
      timers.tick(0)
      expect(callback).toHaveBeenCalledTimes(1)

      timers.tick(2000)
      expect(callback).toHaveBeenCalledTimes(2)
    })

    test('runs multiple timers according to their delays', () => {
      const calls = []

      timers.setFastTimeout(() => calls.push('short'), 1500)
      timers.setFastTimeout(() => calls.push('long'), 4000)

      timers.tick(0)
      timers.tick(2000)
      expect(calls).toEqual(['short'])

      timers.tick(3000)
      expect(calls).toEqual(['short', 'long'])
    })

    test('clearing one timer does not affect other pending timers', () => {
      const shortCallback = jest.fn()
      const longCallback = jest.fn()

      const shortHandle = timers.setFastTimeout(shortCallback, 1500)
      timers.setFastTimeout(longCallback, 4000)

      timers.tick(0)
      timers.clearFastTimeout(shortHandle)
      timers.tick(5000)

      expect(shortCallback).not.toHaveBeenCalled()
      expect(longCallback).toHaveBeenCalledTimes(1)
    })

    test('reset clears scheduled timers as well as the internal clock', () => {
      const callback = jest.fn()

      timers.setFastTimeout(callback, 2000)
      timers.reset()

      expect(timers.now()).toBe(0)
      timers.tick(10000)
      expect(callback).not.toHaveBeenCalled()
    })
  })
})
